def f_gene(R):
    k = R.choice(["row", "row", "row", "cell", "ratio2"])
    if k == "row":
        q, a, w, e = R.choice(GENE_ROWS)
        from kr_sci import it
        return it(q, "%s %%" % num(a), ["%s %%" % num(x) for x in w], e)
    if k == "cell":
        n = R.choice([8, 16, 46, 24, 12, 20])
        return nq("체세포의 염색체 수가 %d개인 생물이 감수 분열로 만든 생식세포의 염색체 수는 몇 개일까요?" % n, n // 2, [n, n * 2, n // 4], "개", "감수 분열 결과 염색체 수가 절반이 되므로 %d ÷ 2 = %d개입니다." % (n, n // 2))
    n = R.choice([1, 2, 3, 4])
    return nq("서로 다른 상염색체에 있는 대립유전자 %d쌍이 모두 이형 접합(예: AaBb…)인 개체에서 만들어질 수 있는 생식세포의 유전자 조합은 최대 몇 가지일까요?" % n, 2 ** n, [2 * n, n, 4 ** n, 2 ** n + 2], "가지",
              "독립적으로 분리되므로 2^%d = %d가지입니다." % (n, 2 ** n))


def f_cellcount(R):
    n = R.choice([46, 8, 16, 24, 12, 20, 14, 18])
    k = R.choice(["mitosis", "g1", "meiosis2", "dna"])
    if k == "mitosis":
        return nq("체세포의 염색체 수가 2n = %d인 생물의 체세포 분열 결과 생긴 딸세포 1개의 염색체 수는 몇 개일까요?" % n, n, [n // 2, n * 2, n // 4], "개", "체세포 분열은 모세포와 염색체 수가 같은 딸세포를 만듭니다. %d개입니다." % n)
    if k == "g1":
        return nq("체세포의 염색체 수가 2n = %d인 생물에서 상동 염색체는 몇 쌍일까요?" % n, n // 2, [n, n * 2, n // 2 + 1], "쌍", "2n = %d이므로 상동 염색체는 %d쌍입니다." % (n, n // 2))
    if k == "meiosis2":
        return nq("체세포의 염색체 수가 2n = %d인 생물에서 감수 1분열이 끝난 직후 세포 1개의 염색체 수는 몇 개일까요?" % n, n // 2, [n, n * 2, n // 4], "개", "감수 1분열에서 상동 염색체가 분리되므로 n = %d개입니다." % (n // 2))
    return nq("체세포 1개의 염색체 수가 2n = %d인 생물에서 감수 분열을 거쳐 만들어진 생식세포 1개의 염색 분체 수는 몇 개일까요?" % n, n // 2, [n, n * 2, n // 4], "개",
              "감수 2분열에서 염색 분체가 분리되므로 생식세포 1개는 염색 분체(염색체) %d개를 가집니다." % (n // 2))


def f_earth(R, kinds):
    k = R.choice(kinds)
    if k == "half":
        T, n = R.choice([(5730, 2), (5730, 3), (1.3e9, 2), (7e8, 1), (4.5e9, 1), (5730, 1), (7e8, 3), (1.3e9, 3)])
        frac = {1: "1/2", 2: "1/4", 3: "1/8"}[n]
        return nq("반감기가 %s년인 방사성 동위 원소가 처음 양의 %s만 남아 있습니다. 경과한 시간은 몇 년일까요?" % (num(T), frac), T * n,
                  [T / n, T * 2 ** n, T * (n + 1), T * (n - 1) if n > 1 else T / 2], "년", "1/2씩 %d번 줄었으므로 반감기 %d번이 지났습니다. %s × %d = %s년입니다." % (n, n, num(T), n, num(T * n)))
    if k == "half2":
        m, n = R.choice([(80, 2), (64, 3), (100, 1), (40, 2), (96, 4), (120, 3)])
        return nq("방사성 동위 원소 %d g이 반감기를 %d번 지나면 남는 양은 몇 g일까요?" % (m, n), m / 2 ** n, [m / (2 * n), m - m / 2 ** n, m / 2 if n > 1 else m / 4], "g", "%d × (1/2)^%d = %s g입니다." % (m, n, num(m / 2 ** n)))
    if k == "kepler":
        a = R.choice([4, 9, 16, 1.52, 5.2, 0.39, 25])
        T = a ** 1.5
        return nq("어떤 행성의 공전 궤도 긴반지름이 %s AU일 때 공전 주기는 약 몇 년일까요? (케플러 제3법칙: T² = a³, T는 년, a는 AU)" % num(a), T, [a, a * a, a ** 3, T * 2], "년", "T² = %s³이므로 T = %s년입니다." % (num(a), num(T)))
    if k == "kepT":
        T = R.choice([8, 27, 64, 125, 1000])
        a = round(T ** (2 / 3))
        return nq("어떤 소행성의 공전 주기가 %d년일 때 공전 궤도 긴반지름은 몇 AU일까요? (케플러 제3법칙: T² = a³)" % T, a, [T, T / 2, T * T, a * a], "AU", "a³ = %d² = %d이므로 a = %d AU입니다." % (T, T * T, a))
    if k == "hubble":
        d = R.choice([10, 20, 50, 100, 200, 30, 40])
        return nq("허블 상수를 70 km/s/Mpc라고 할 때, %d Mpc 떨어진 은하의 후퇴 속도는 몇 km/s일까요?" % d, 70 * d, [70 / d, d / 70, 70 + d], "km/s", "v = H × d = 70 × %d = %s km/s입니다." % (d, num(70 * d)))
    if k == "dist":
        v = R.choice([1400, 3500, 7000, 2100, 700, 14000])
        return nq("허블 상수를 70 km/s/Mpc라고 할 때, 후퇴 속도가 %s km/s인 은하까지의 거리는 몇 Mpc일까요?" % num(v), v / 70, [v * 70, 70 / v, v - 70], "Mpc", "d = v ÷ H = %s ÷ 70 = %s Mpc입니다." % (num(v), num(v / 70)))
    if k == "lum":
        r, t = R.choice([(2, 1), (1, 2), (3, 1), (10, 1), (2, 2), (1, 0.5)])
        L = r * r * t ** 4
        return nq("어떤 별의 반지름이 태양의 %s배이고 표면 온도가 태양의 %s배일 때, 광도는 태양의 몇 배일까요? (광도 ∝ 반지름² × 표면 온도⁴)" % (num(r), num(t)), L, [r * t, r * r * t, r * t ** 4, r ** 4 * t * t], "배",
                  "L ∝ R²T⁴ = %s² × %s⁴ = %s배입니다." % (num(r), num(t), num(L)))
    if k == "mag":
        dm = R.choice([5, 10, 1, 2, 15])
        b = {1: 2.5, 2: 6.3, 5: 100, 10: 10000, 15: 1000000}[dm]
        return nq("두 별의 겉보기 등급 차이가 %d등급일 때, 밝은 별은 어두운 별보다 약 몇 배 밝을까요?" % dm, b, [dm * 2.5, dm * 100 if dm > 1 else 10, 2.5 ** (dm + 1), dm], "배",
                  "1등급 차이는 약 2.5배, 5등급 차이는 100배입니다. %d등급 차이는 약 %s배입니다." % (dm, num(b)))
    v, t = R.choice([(5, 2e6), (2, 1e7), (4, 5e6), (10, 3e6), (3, 4e6), (6, 5e6), (8, 2e6), (2, 3e7)])
    return nq("해령에서 판이 매년 %d cm씩 멀어집니다. 해령 축에서 %s km 떨어진 해양 지각의 나이는 약 몇 년일까요?" % (v, num(v * t / 100000)), t, [v * v * t, t / 10, t * 10], "년",
              "%s km = %s cm이므로 나이 = %s ÷ %d = %s년입니다." % (num(v * t / 100000), num(v * t), num(v * t), v, num(t)))


