          [("바이러스는 세포로 이루어진 생물이다.", "바이러스는 세포 구조가 없습니다."), ("대조군은 조작 변인을 변화시킨 집단이다.", "조작 변인을 변화시킨 집단은 실험군입니다."), ("항상성은 몸의 상태가 계속 바뀌는 성질이다.", "항상성은 몸의 상태를 일정하게 유지하는 성질입니다.")],
